-- P.U.M.A.: direzioni regionali, mappa Comando -> Direzione e livello di visibilita' dell'utente (comando | regione | nazionale).
CREATE TABLE IF NOT EXISTS puma_direzioni(id INTEGER PRIMARY KEY, nome TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS puma_comando_dir(comando_id INTEGER PRIMARY KEY REFERENCES comandi(id) ON DELETE CASCADE, direzione_id INTEGER REFERENCES puma_direzioni(id));
CREATE TABLE IF NOT EXISTS puma_livello_utente(utente_id INTEGER PRIMARY KEY REFERENCES utenti(id) ON DELETE CASCADE,
  livello TEXT NOT NULL DEFAULT 'comando' CHECK(livello IN ('comando','regione','nazionale')));
INSERT OR IGNORE INTO puma_direzioni(nome) VALUES ('Piemonte'),('Valle d''Aosta'),('Lombardia'),('Trentino-Alto Adige'),('Veneto'),('Friuli Venezia Giulia'),('Liguria'),('Emilia-Romagna'),('Toscana'),('Umbria'),('Marche'),('Lazio'),('Abruzzo'),('Molise'),('Campania'),('Puglia'),('Basilicata'),('Calabria'),('Sicilia'),('Sardegna');
