ia'),('RG','Sicilia'),('SR','Sicilia'),('TP','Sicilia'),('CA','Sardegna'),('NU','Sardegna'),('OR','Sardegna'),('SS','Sardegna'),('SU','Sardegna'))) m ON m.sigla=c.sigla JOIN puma_direzioni d ON d.nome=m.reg;
